func TestAScannedRuleInPiecesKeepsItsSlantWhenThePiecesAreOneRun(emonT *testing.T) {
	// D513: a rule of a scan, turned by 0.6 degrees and found in three pieces, is one run of the tracer alone; its centre line follows the pieces, it is not flat.
	var pa *port.Cells = port.NewCells()
	var im *port.Cells = port.NewCells()
	var grl *port.Cells = port.NewCells()
	var gfl *port.Cells = port.NewCells()
	var ggp *port.Cells = port.NewCells()
	var grg *port.Cells = port.NewCells()
	var refs *port.Cells = port.NewCells()
	var hl *port.Cells = port.NewCells()
	var fx *port.Cells = port.NewCells()
	var gfa *port.Cells = port.NewCells()
	var inks *port.Cells = port.NewCells()
	var rules *port.Cells = port.NewCells()
	var prims *port.Cells = port.NewCells()
	var oblocks *port.Cells = port.NewCells()
	var owords *port.Cells = port.NewCells()
	var words *port.Cells = port.NewCells()
	var etext *port.Cells = port.NewCells()
	var feats *port.Cells = port.NewCells()
	var m int32 = evidence.ImNew(im, 1, 10000, 10000, 40000, 40000, 7, 600, 600)
	port.AssertEq(emonT, m, 0, "the image placement")
	// the engine's line separator (a `bt-line` block) under the pieces joins them to one group: two tracer pieces are never joined to each other
	var b int32 = evidence.ObNew(oblocks, 1, 12000, 15100, 38000, 15170, evidence.ObBlock(), -1, 0)
	evidence.ObSet(oblocks, b, evidence.ObfBtype(), 3)
	guTrace(rules, 12000, 15000, 20000, 15083, 900)
	guTrace(rules, 20000, 15083, 30000, 15187, 900)
	guTrace(rules, 30000, 15187, 38000, 15270, 900)
	port.AssertEq(emonT, guFuse(1, inks, rules, prims, oblocks, owords, words, etext, pa, im, feats, grl, gfl, ggp, grg, refs, hl, fx, gfa), 1, "fused")
	port.AssertEq(emonT, glayer.GgpCount(ggp), 1, "one group: the three pieces and the line the engine saw under them")
	port.AssertEq(emonT, glayer.GgpGet(ggp, 0, 5), 3, "three tracer members")
	port.AssertEq(emonT, glayer.GgpGet(ggp, 0, 7), 1, "and one OCR member")
	port.AssertEq(emonT, glayer.GrlCount(grl), 1, "one rule: the run")
	port.AssertEq(emonT, glayer.GrlGet(grl, 0, 16), 530, "by row 530")
	port.AssertEq(emonT, glayer.GrlGet(grl, 0, 10), glayer.GoH(), "horizontal")
	port.AssertEq(emonT, glayer.GrlGet(grl, 0, 5), 12000, "from the left end of the first piece")
	port.AssertEq(emonT, glayer.GrlGet(grl, 0, 7), 38000, "to the right end of the last")
	port.AssertThat(emonT, (glayer.GrlGet(grl, 0, 6) >= 14998) && (glayer.GrlGet(grl, 0, 6) <= 15002), "at the height of the first piece there")
	port.AssertThat(emonT, (glayer.GrlGet(grl, 0, 8) >= 15268) && (glayer.GrlGet(grl, 0, 8) <= 15272), "and at the height of the last piece at the other end: the line is not flat")
	port.AssertThat(emonT, (glayer.GrlGet(grl, 0, 11) > 17900) && (glayer.GrlGet(grl, 0, 11) < 17980), "its angle is 0.6 degrees (page space has y down: 179.4)")
	port.AssertThat(emonT, glayer.GrlGet(grl, 0, 2) <= 14950, "its box holds the line whole: the top")
	port.AssertThat(emonT, glayer.GrlGet(grl, 0, 4) >= 15300, "and the bottom")
	port.AssertEq(emonT, glayer.GlCheck(grl, gfl, ggp, grg, refs), 0, "sound")
}

